<g fill="#d2d7c3"><ellipse cx="215" cy="221" rx="2.4" ry="3"/><ellipse cx="224" cy="225" rx="2.4" ry="3"/><ellipse cx="233" cy="230" rx="2.4" ry="3"/></g>
